hl.bind(mainMod .. " + " .. "P", hl.dsp.window.pseudo())

-- dwindle

hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "R", hl.dsp.exec_cmd("~/.config/hypr/scripts/reload.sh"))

hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "T", hl.dsp.exec_cmd("~/.config/hypr/scripts/sys-cleaning.sh"))

hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "L", hl.dsp.exec_cmd("hyprlock"))

hl.bind(
	mainMod .. " + " .. "D",
	hl.dsp.exec_cmd(
		"STATUS=$(dunstctl is-paused); if [ local_var_STATUS=false ]; then notify-send -u critical DND Enabled Notifications silenced ; sleep 0.5; dunstctl set-paused true; else dunstctl set-paused false; notify-send -u low DND Disabled Notifications active ; fi"
	)
)

-- Move focus with mainMod + vim key

